"""Optional dependency-aware ordering of autogenerated operations.

This module implements an *optional* ordering stage for autogenerate.
When enabled (see :ref:`autogenerate_ordering`), the operations within
each :class:`.UpgradeOps` and :class:`.DowngradeOps` container are
reordered so that schema-qualified object dependencies declared by the
operations themselves are respected:

* an operation is only moved within the region in which dependencies
  are declared; operations that don't declare any dependencies (such as
  unknown custom operations or :class:`.ExecuteSQLOp`) act as ordering
  barriers that no other operation may be moved across.

* operations that have no dependency relationship keep their original
  relative order.

* container boundaries are preserved: the contents of
  :class:`.ModifyTableOps` (which also delimit batch mode blocks) are
  never moved out of their container; the container participates in
  ordering as an atomic unit.

* dependency cycles are reported as an :class:`.OpOrderingError`
  naming the objects and operations involved.  Operations whose work
  can be deferred (such as foreign key constraints declared with
  ``use_alter=True``) may explicitly split off post operations via
  :meth:`.MigrateOperation.split_off_post_ops`; the ordering stage
  never guesses how to break a cycle on its own.

.. versionadded:: 1.21.0

"""

from __future__ import annotations

import heapq
from typing import TYPE_CHECKING

from .. import util

if TYPE_CHECKING:
    from ..operations.ops import MigrateOperation
    from ..operations.ops import OpContainer
    from ..operations.ops import OpDependency

__all__ = ("OpOrderingError", "sort_ops")


class OpOrderingError(util.CommandError):
    """Raised when operations cannot be ordered consistently.

    This occurs when the dependency declarations of the operations
    within a sortable region form a cycle.  The error message includes
    the concrete cycle of objects and operations that was detected.
    """


def sort_ops(op_container: OpContainer) -> OpContainer:
    """Sort the operations within an :class:`.UpgradeOps` or
    :class:`.DowngradeOps` container, in place.

    Operations are reordered according to the :class:`.OpDependency`
    declarations returned by :meth:`.MigrateOperation.get_dependencies`,
    following the rules described in the module docstring.  The
    container is modified in place and also returned, for convenience.

    Before sorting, each operation is given the chance to split off
    deferred "post" operations via
    :meth:`.MigrateOperation.split_off_post_ops`; post operations are
    ordered separately and placed after the main body of operations.

    """
    main_ops: list[MigrateOperation] = []
    post_ops: list[MigrateOperation] = []
    for op in op_container.ops:
        main_op, posts = op.split_off_post_ops()
        main_ops.append(main_op)
        post_ops.extend(posts)

    sorted_ops = _sort_with_barriers(main_ops)
    sorted_ops.extend(_sort_with_barriers(post_ops))
    op_container.ops[:] = sorted_ops
    return op_container


def _sort_with_barriers(
    op_list: list[MigrateOperation],
) -> list[MigrateOperation]:
    """Sort a flat list of operations, segment by segment.

    Operations whose dependency declaration is unknown (``None``) act
    as barriers: the list is split into segments at each barrier, and
    each segment is sorted independently, so no operation ever moves
    across a barrier.
    """
    result: list[MigrateOperation] = []
    segment: list[MigrateOperation] = []
    segment_deps: list[OpDependency] = []

    def flush() -> None:
        if segment:
            result.extend(_toposort(segment, segment_deps))
            segment.clear()
            segment_deps.clear()

    for op in op_list:
        deps = op.get_dependencies()
        if deps is None:
            flush()
            result.append(op)
        else:
            segment.append(op)
            segment_deps.append(deps)
    flush()
    return result


# lifecycle events on a single object, in the order in which they must
# happen: an object is created before it is read, and read before it
# is dropped.  A create/drop pair on the *same* object is ambiguous
# (temporary object vs. drop-and-recreate), so no edge is added and
# the original relative order is kept.
_LIFECYCLE_EDGES = (
    ("creates", "reads"),
    ("reads", "drops"),
)


def _toposort(
    op_list: list[MigrateOperation], deps: list[OpDependency]
) -> list[MigrateOperation]:
    """Stable topological sort of a single barrier-free segment."""
    count = len(op_list)
    if count < 2:
        return list(op_list)

    successors: list[set[int]] = [set() for _ in range(count)]
    indegree = [0] * count
    for earlier_attr, later_attr in _LIFECYCLE_EDGES:
        earlier: dict[object, list[int]] = {}
        for idx, dep in enumerate(deps):
            for ref in getattr(dep, earlier_attr):
                earlier.setdefault(ref, []).append(idx)
        for idx, dep in enumerate(deps):
            for ref in getattr(dep, later_attr):
                for src in earlier.get(ref, ()):
                    if src != idx and idx not in successors[src]:
                        successors[src].add(idx)
                        indegree[idx] += 1

    heap = [idx for idx in range(count) if indegree[idx] == 0]
    heapq.heapify(heap)
    order: list[int] = []
    while heap:
        idx = heapq.heappop(heap)
        order.append(idx)
        for nxt in sorted(successors[idx]):
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) < count:
        remaining = set(range(count)) - set(order)
        cycle = _find_cycle(remaining, successors)
        raise OpOrderingError(_format_cycle(op_list, deps, cycle))

    return [op_list[idx] for idx in order]


def _find_cycle(remaining: set[int], successors: list[set[int]]) -> list[int]:
    """Find a concrete cycle within the remaining subgraph."""
    color: dict[int, int] = {}
    stack: list[int] = []
    for start in sorted(remaining):
        if start in color:
            continue
        color[start] = 1
        stack.append(start)
        work = [(start, iter(sorted(successors[start] & remaining)))]
        while work:
            node, it = work[-1]
            advanced = False
            for nxt in it:
                if color.get(nxt) == 1:
                    return stack[stack.index(nxt):] + [nxt]
                if nxt not in color:
                    color[nxt] = 1
                    stack.append(nxt)
                    work.append(
                        (nxt, iter(sorted(successors[nxt] & remaining)))
                    )
                    advanced = True
                    break
            if not advanced:
                work.pop()
                color[node] = 2
                stack.pop()
    return sorted(remaining)  # pragma: no cover


def _shared_refs(earlier: OpDependency, later: OpDependency) -> str:
    shared = (
        (earlier.creates & (later.reads | later.drops))
        | (earlier.reads & later.drops)
    )
    return ", ".join(repr(ref) for ref in sorted(shared))


def _describe_op(op: MigrateOperation) -> str:
    cls_name = type(op).__name__
    for attr in (
        "table_name",
        "source_table",
        "old_table_name",
        "index_name",
        "constraint_name",
    ):
        value = getattr(op, attr, None)
        if value:
            return "%s(%r)" % (cls_name, value)
    return cls_name


def _dep_summary(deps: OpDependency) -> str:
    parts = []
    for attr in ("creates", "reads", "drops"):
        values = getattr(deps, attr)
        if values:
            parts.append(
                "%s: %s"
                % (attr, ", ".join(repr(ref) for ref in sorted(values)))
            )
    return "; ".join(parts)


def _format_cycle(
    op_list: list[MigrateOperation],
    deps: list[OpDependency],
    cycle: list[int],
) -> str:
    lines = [
        "Cannot determine a consistent ordering for migration "
        "operations: dependency cycle detected."
    ]
    for cur, nxt in zip(cycle, cycle[1:]):
        lines.append(
            "  [%d] %s (%s)"
            % (cur, _describe_op(op_list[cur]), _dep_summary(deps[cur]))
        )
        lines.append(
            "    -> must precede [%d] via %s"
            % (nxt, _shared_refs(deps[cur], deps[nxt]))
        )
    lines.append(
        "  ...cycle returns to [%d] %s"
        % (cycle[0], _describe_op(op_list[cycle[0]]))
    )
    lines.append(
        "Operations whose effects may be deferred (such as foreign key "
        "constraints declared with use_alter=True) can be split into "
        "post operations via MigrateOperation.split_off_post_ops(); "
        "the ordering stage does not attempt to break cycles on its "
        "own."
    )
    return "\n".join(lines)
